/// HTTP method of a webhook request.
///
/// Note: the zero value <code>WEBHOOK_HTTP_METHOD_UNSPECIFIED</code> is not "no method" but means <code>POST</code>, the default. It keeps its released name for wire and source compatibility; a webhook written with it is stored and sent as POST, and <code>Webhook.http_method</code> then reads back <code>WEBHOOK_HTTP_METHOD_POST</code>.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash, PartialOrd, Ord, ::prost::Enumeration)]
#[repr(i32)]
pub enum WebhookHttpMethod {
    /// Unspecified: <code>POST</code>.
    Unspecified = 0,
    /// POST.
    Post = 1,
    /// PUT.
    Put = 2,
}
impl WebhookHttpMethod {
    /// String value of the enum field names used in the ProtoBuf definition.
    ///
    /// The values are not transformed in any way and thus are considered stable
    /// (if the ProtoBuf definition does not change) and safe for programmatic use.
    pub fn as_str_name(&self) -> &'static str {
        match self {
            Self::Unspecified => "WEBHOOK_HTTP_METHOD_UNSPECIFIED",
            Self::Post => "WEBHOOK_HTTP_METHOD_POST",
            Self::Put => "WEBHOOK_HTTP_METHOD_PUT",
        }
    }
    /// Creates an enum from field names used in the ProtoBuf definition.
    pub fn from_str_name(value: &str) -> ::core::option::Option<Self> {
        match value {
            "WEBHOOK_HTTP_METHOD_UNSPECIFIED" => Some(Self::Unspecified),
            "WEBHOOK_HTTP_METHOD_POST" => Some(Self::Post),
            "WEBHOOK_HTTP_METHOD_PUT" => Some(Self::Put),
            _ => None,
        }
    }
}
